def rotate_string(s: str, k: int) -> str:
    if not s:
        return s  # Return empty string if input is empty

    k %= len(s)  # Adjust k to be within the range of the string length
    return s[k:] + s[:k]

def snake_to_camel(name: str) -> str:
    # Remove leading underscores
    name = name.lstrip('_')

    # Split the name by underscore, capitalize each part except the first one, and join them together
    return ''.join(word.capitalize() if i != 0 else word for i, word in enumerate(name.split('_')))

